code.java:
import java.util.*;

public class Decibinary {
    static final int BITS = 20;          // 2^19 > MAXV, so higher positions are forced to 0
    static final int MAXV = 285115;      // cumulative count exceeds 10^16 within this range
    static long[][] count;               // count[b][v] = #numerals over positions 0..b equal to v
    static long[] numWays, prefix;

    static void precompute() {
        count = new long[BITS][MAXV + 1];
        for (int v = 0; v <= MAXV; v++) count[0][v] = (v <= 9) ? 1 : 0;
        for (int b = 1; b < BITS; b++) {
            int w = 1 << b;
            for (int v = 0; v <= MAXV; v++) {
                long sum = 0;
                for (int a = 0; a <= 9 && a * w <= v; a++) sum += count[b - 1][v - a * w];
                count[b][v] = sum;
            }
        }
        numWays = new long[MAXV + 1];
        prefix  = new long[MAXV + 1];
        long run = 0;
        for (int v = 0; v <= MAXV; v++) {
            numWays[v] = count[BITS - 1][v];
            run += numWays[v];
            prefix[v] = run;
        }
    }

    // #numerals equal to v using only positions 0..p-1
    static long waysBelow(int p, int v) {
        return (p == 0) ? (v == 0 ? 1 : 0) : count[p - 1][v];
    }

    public static String decibinaryNumbers(long x) {
        // smallest value d with prefix[d] >= x (binary search)
        int lo = 0, hi = MAXV, d = MAXV;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            if (prefix[mid] >= x) { d = mid; hi = mid - 1; } else lo = mid + 1;
        }
        long k = x - (d == 0 ? 0 : prefix[d - 1]);   // 1-based rank within value d
        int[] digits = new int[BITS];
        int remaining = d;
        for (int p = BITS - 1; p >= 0; p--) {
            int w = 1 << p;
            for (int a = 0; a <= 9 && a * w <= remaining; a++) {
                long cnt = waysBelow(p, remaining - a * w);
                if (k <= cnt) { digits[p] = a; remaining -= a * w; break; }
                k -= cnt;
            }
        }
        StringBuilder sb = new StringBuilder();
        boolean started = false;
        for (int p = BITS - 1; p >= 0; p--) {
            if (digits[p] != 0) started = true;
            if (started) sb.append(digits[p]);
        }
        return started ? sb.toString() : "0";
    }
}

